insert into public.challenges (id, title, description, category, proof_type, estimated_duration_seconds, enabled)
values
  ('ch_01', 'نشرة أخبار الهزيمة', 'قدّم نشرة أخبار درامية بصوت مذيع جاد جداً تعلن فيها خبر خسارتك الفادحة ولبسك للشايب قدام كل الموجودين!', 'acting', 'voice', 25, true),
  ('ch_02', 'ضحكة الشرير الكبير', 'سجّل ضحكة شريرة مدتها ١٠ ثواني زي أشرار الأفلام القديمة بعد ما الشايب قفل عليك القعدة.', 'voice', 'voice', 15, true),
  ('ch_03', 'أبوخ نكتة في التاريخ', 'قول أو اكتب أسخف وأبوخ نكتة تعرفها، ولازم تضحك عليها لوحدك في الآخر!', 'comedy', 'text', 20, true),
  ('ch_04', 'اللقب الملكي للفائز', 'اخترع لقب ملكي فخم ومضحك لأول واحد فلت من الشايب في الجولة دي واكتبه في الشات بكل احترام.', 'group', 'text', 20, true),
  ('ch_05', 'شاعر القهوة', 'اكتب ٣ أبيات شعر بالمصري العامي تمدح فيهم براعة الكسبان وتتحسر على حظك مع الشايب.', 'poetry', 'text', 45, true),
  ('ch_06', 'معلّق الكورة المصري', 'قلّد معلق كورة مصري متحمس وهو بيوصف اللحظة التاريخية اللي سحبت فيها الشايب في الدقيقة التسعين!', 'voice', 'voice', 25, true),
  ('ch_07', 'تبّاع الميكروباص', 'قلّد صوت تبّاع ميكروباص بينادي على خط (رمسيس - الجيزة - موقف الشايب) لمدة ١٥ ثانية!', 'voice', 'voice', 15, true),
  ('ch_08', 'عمو الحاج على القهوة', 'اتكلم لمدة ٢٠ ثانية بصوت راجل عجوز قاعد على القهوة بيلوم الجيل الجديد إنه مش بيعرف يلعب كوتشينة.', 'acting', 'voice', 20, true),
  ('ch_09', 'قصة حب مع الكشري', 'ابعت ريكورد صوتي بتعلن فيه حبك الدرامي لطبق كشري بالدقة والتقلية كأنه مشهد سينمائي مؤثر.', 'voice', 'voice', 20, true),
  ('ch_10', 'المؤتمر الصحفي للمدرب', 'اشرح أسباب خسارتك كأنك مدير فني لمنتخب الكوتشينة في مؤتمر صحفي وبتحمل المسؤولية للرطوبة والورق!', 'acting', 'text', 30, true),
  ('ch_11', 'إعلان شاي في الخمسينة', 'اخترع إعلان تلفزيوني مضحك لكوباية شاي على القهوة بتنسّي الواحد صدمة الخسارة في الشايب.', 'comedy', 'text', 30, true),
  ('ch_12', 'موزّع الألقاب', 'طلع لقب مصري كوميدي لكل لاعب موجود معاك في القعدة واكتبهم كلهم في رسالة واحدة.', 'group', 'text', 40, true),
  ('ch_13', 'رئيس رابطة الخسرانين', 'عرّف نفسك رسمياً كـ «رئيس رابطة الخسرانين والملبوسين في الشايب» ووجّه كلمة ترحيب للأعضاء.', 'comedy', 'text', 25, true),
  ('ch_14', 'خمس أصوات في جملة', 'قول جملة «الشايب لبس فيا يا جدعان» بخمس نبرات صوت خيالية ومختلفة ورا بعض!', 'voice', 'voice', 25, true),
  ('ch_15', 'الملحمة التاريخية للبطل', 'اوصف اللاعب اللي كسب الجولة كأنه بطل تاريخي أسطوري حرر القهوة من بطش الشايب.', 'poetry', 'text', 30, true),
  ('ch_16', 'مرافعة محامي الكوتشينة', 'اتقمص دور محامي في محكمة وبتترافع عن طريقة لعبك الكارثية قدام القاضي وبتطالب بالبراءة!', 'acting', 'text', 35, true),
  ('ch_17', 'اعتذار رسمي للورق', 'اكتب بيان اعتذار رسمي ومؤثر لورق الكوتشينة على الأداء اللي قدمته في الجولة دي.', 'comedy', 'text', 25, true),
  ('ch_18', 'أفيش الفيلم الهندي', 'ألّف اسم فيلم سينمائي درامي مع شعار دعائي يوصف مأساة الجولة اللي خسرتها دي.', 'comedy', 'text', 20, true),
  ('ch_19', 'مثل شعبي جديد', 'اخترع مثل شعبي مصري جديد عن سوء الحظ واللبس في الشايب بحيث يبان كأنه مثل قديم بجد!', 'poetry', 'text', 20, true),
  ('ch_20', 'النشرة الجوية لحظك', 'قدّم نشرة جوية بتحذر فيها من عاصفة نحس شديدة وأمطار شايب رعدية على منطقتك في القعدة.', 'acting', 'text', 25, true),
  ('ch_21', 'لقب شايب المعمورة', 'لقبك في القعدة بقى رسمياً «شايب المعمورة» للجولة الجاية! اكتب في الشات: أنا شايب المعمورة وافتخر!', 'in_game', 'in_game', 15, true),
  ('ch_22', 'ختم الشايب 👴', 'استخدم إيموجي الراجل العجوز (👴) في أول وآخر رسالتك في الشات ودلّع الشايب!', 'in_game', 'in_game', 15, true),
  ('ch_23', 'مانشيت الجورنال', 'اكتب مانشيت جورنال عريض ومثير للجدل عن سقوطك المدوي في فخ الشايب النهارده.', 'comedy', 'text', 20, true),
  ('ch_24', 'خطاب تنمية بشرية للخسرانين', 'سجّل أو اكتب كلمة تحفيزية ساخرة بتواسي بيها كل اللي بيلبسوا في الشايب وتقولهم إزاي يتصالحوا مع الشايب.', 'voice', 'voice', 25, true),
  ('ch_25', 'أكلة الشايب المخصوص', 'اخترع صنف أكل جديد في منيو مطعم شعبي مستوحى من كارت الشايب واكتب مكوناته وسعره!', 'comedy', 'text', 25, true),
  ('ch_26', 'قصة مأساوية في ٣ سطور', 'احكي اللي حصل معاك في الجولة دي على شكل قصة حزينة جداً من ٣ سطور بس.', 'poetry', 'text', 25, true),
  ('ch_27', 'السيرة الذاتية للشايب', 'ألّف سيرة ذاتية كوميدية لكارت الشايب: اسمه بالكامل، شغله القديم، وليه رافض يتجوز أي كارت تاني!', 'comedy', 'text', 30, true),
  ('ch_28', 'مذيع التوك شو', 'اعمل حوار تلفزيوني سريع مع الفائز في الجولة واسأله سؤالين عن سر الهروب من الشايب.', 'group', 'text', 30, true),
  ('ch_29', '٣ حجج خزعبليّة', 'اكتب ٣ أعذار وحجج خيالية ومستحيلة تبرر بيها ليه إنت اللي سحبت الشايب في الآخر.', 'comedy', 'text', 25, true),
  ('ch_30', 'خطبة الوداع للورق', 'وجّه خطبة وداع درامية لكارت الشايب قبل ما تبدأ الجولة الجديدة واطلب منه يشوف حد غيرك يلبس فيه!', 'acting', 'text', 25, true)
